<template>
  <div class="flex flex-col gap-1.5">
    <Select
      class="border-border"
      v-bind="componentField"
      :disabled="disabled"
      @update:model-value="$emit('update:model-value', $event)"
    >
      <SelectTrigger
        :id="componentField.name"
        :class="cn('gap-2', triggerClass)"
        :is-loading="loading"
        :disabled="loading"
      >
        <p v-if="loading">Loading items...</p>
        <SelectValue
          v-else
          :class="cn('text-foreground', !componentField.modelValue && 'text-muted-foreground')"
          placeholder="Select an option"
        >
          {{ selectedLabel }}
        </SelectValue>
      </SelectTrigger>
      <SelectContent>
        <p v-if="!items.length" class="px-3 text-sm text-accent-foreground select-none">No items to select</p>
        <SelectItem v-for="(item, index) in items" v-else :key="index" :value="item.value">
          {{ item.name ?? item.value }}
        </SelectItem>
      </SelectContent>
    </Select>
    <p v-if="error" class="p-2 text-sm text-destructive select-none">{{ error }}</p>
  </div>
</template>

<script setup lang="ts">
import type { ComponentFieldBindingObject } from 'vee-validate';
import type { AcceptableValue } from 'reka-ui';
import { isEqual } from 'lodash';
import { cn } from '@/lib/utils';

interface Props {
  componentField: ComponentFieldBindingObject;
  items: SelectItem<string | number | Record<string, string[]>>[];
  triggerClass?: string;
  disabled?: boolean;
  loading?: boolean;
  error?: string;
}

const props = defineProps<Props>();

// Render the selected label from `items` rather than relying on reka-ui's
// optionsSet, which is only populated once the dropdown has been opened — so an
// async-loaded, programmatically-set value would otherwise show the placeholder
// until first open.
const selectedLabel = computed(() => {
  const selected = props.items.find((item) => isEqual(item.value, props.componentField.modelValue));
  return selected ? (selected.name ?? String(selected.value)) : 'Select an option';
});

interface Emits {
  (e: 'update:model-value', value: AcceptableValue): void;
}

defineEmits<Emits>();
</script>

<style lang="scss" scoped></style>
